<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarRemitente, guardarRemitente, listarRemitentes, opcionesDocumentoExterno, registrarDocumentoExterno } from '../services/externo'
import type { RemitenteExterno } from '../interfaces/externo.interface'
import type { CatalogOption } from '../../interfaces/documento'
const items=ref<RemitenteExterno[]>([]),tipos=ref<CatalogOption[]>([]),criterio=ref(''),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),docModal=ref(false),editing=ref<number|null>(null),selected=ref<RemitenteExterno|null>(null)
const form=reactive({tipo:1 as 1|2,nombre:'',apellido_paterno:'',apellido_materno:'',dni:'',razon_social:'',ruc:'',celular:'',telefono_fijo:'',email:''}),doc=reactive({tipo_documento_id:0,numero:'',asunto:'',archivo:null as File|null})
async function load(page=1){loading.value=true;error.value='';try{const r=await listarRemitentes(criterio.value,page);items.value=r.data;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron cargar los remitentes.'}finally{loading.value=false}}
function open(item?:RemitenteExterno){editing.value=item?.id||null;Object.assign(form,{tipo:item?.tipo||1,nombre:item?.nombre||'',apellido_paterno:item?.apellido_paterno||'',apellido_materno:item?.apellido_materno||'',dni:item?.dni||'',razon_social:item?.razon_social||'',ruc:item?.ruc||'',celular:item?.celular||'',telefono_fijo:item?.telefono_fijo||'',email:item?.email||''});modal.value=true}
function validate(){if(!/^\d{9}$/.test(form.celular))return'El celular debe tener 9 dígitos.';if(!form.email.includes('@'))return'Ingrese un correo válido.';if(form.tipo===1&&(!form.nombre||!form.apellido_paterno||!form.apellido_materno||!/^\d{8}$/.test(form.dni)))return'Complete nombres, apellidos y DNI de 8 dígitos.';if(form.tipo===2&&(!form.razon_social||!/^\d{11}$/.test(form.ruc)))return'Complete razón social y RUC de 11 dígitos.';return''}
async function save(){error.value=validate();if(error.value)return;saving.value=true;try{await guardarRemitente(editing.value,{...form});success.value=editing.value?'Remitente actualizado.':'Remitente registrado.';modal.value=false;await load(editing.value?pagination.current:1)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo guardar.'}finally{saving.value=false}}
function openDoc(i:RemitenteExterno){selected.value=i;Object.assign(doc,{tipo_documento_id:0,numero:'',asunto:'',archivo:null});docModal.value=true}
async function saveDoc(){if(!selected.value||!doc.tipo_documento_id||!doc.numero.trim()||!doc.asunto.trim()){error.value='Complete tipo, número y asunto del documento.';return}const data=new FormData();data.append('tipo_documento_id',String(doc.tipo_documento_id));data.append('numero',doc.numero);data.append('asunto',doc.asunto);if(doc.archivo)data.append('archivo',doc.archivo);saving.value=true;try{await registrarDocumentoExterno(selected.value.id,data);success.value='Documento externo registrado.';docModal.value=false;await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo registrar el documento.'}finally{saving.value=false}}
async function remove(i:RemitenteExterno){if(!confirm('¿Eliminar este remitente?'))return;try{await eliminarRemitente(i.id);await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo eliminar.'}}
function display(i:RemitenteExterno){return i.tipo===2?i.razon_social:[i.nombre,i.apellido_paterno,i.apellido_materno].filter(Boolean).join(' ')}
onMounted(async()=>{const r=await opcionesDocumentoExterno();tipos.value=r.tipos_documento;await load()})
</script>
<template><div class="external"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Trámite externo / Remitentes</nav><header class="hero"><div class="mark">EXT</div><div><small>Trámite externo</small><h1>Remitentes y documentos</h1><p>Gestiona personas o empresas y registra los documentos que presentan.</p></div><strong>{{pagination.total}} remitentes</strong><button @click="open()">+ Nuevo remitente</button></header><div v-if="success" class="flash">✓ {{success}}</div><div v-if="error" class="flash error">{{error}}</div><form class="filters" @submit.prevent="load()"><label><span>Nombre, DNI, razón social o RUC</span><input v-model.trim="criterio" placeholder="Buscar remitente"></label><button>Buscar</button><button type="button" class="clear" @click="criterio='';load()">Limpiar</button></form><div v-if="loading" class="notice">Cargando remitentes…</div><div v-else-if="!items.length" class="notice">No hay remitentes registrados.</div><section v-else class="cards"><article v-for="i in items" :key="i.id"><header><div class="avatar">{{i.tipo===2?'PJ':'PN'}}</div><div><small>{{i.tipo===2?'Persona jurídica':'Persona natural'}}</small><h2>{{display(i)}}</h2><span>{{i.tipo===2?i.ruc:i.dni}}</span></div></header><dl><div><dt>Celular</dt><dd>{{i.celular}}</dd></div><div><dt>Correo</dt><dd>{{i.email}}</dd></div><div><dt>Documentos</dt><dd>{{i.documentos_count||0}}</dd></div></dl><footer><button @click="openDoc(i)">+ Documento</button><button class="edit" @click="open(i)">Editar</button><button class="delete" @click="remove(i)">Eliminar</button></footer></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><section class="modal"><header><div><small>Directorio externo</small><h2>{{editing?'Editar':'Registrar'}} remitente</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="save"><label><span>Tipo de persona</span><select v-model="form.tipo"><option :value="1">Persona natural</option><option :value="2">Persona jurídica</option></select></label><div v-if="form.tipo===1" class="grid"><label><span>Nombres *</span><input v-model.trim="form.nombre"></label><label><span>Apellido paterno *</span><input v-model.trim="form.apellido_paterno"></label><label><span>Apellido materno *</span><input v-model.trim="form.apellido_materno"></label><label><span>DNI *</span><input v-model.trim="form.dni" maxlength="8"></label></div><div v-else class="grid"><label><span>Razón social *</span><input v-model.trim="form.razon_social"></label><label><span>RUC *</span><input v-model.trim="form.ruc" maxlength="11"></label></div><div class="grid"><label><span>Celular *</span><input v-model.trim="form.celular" maxlength="9"></label><label><span>Teléfono fijo</span><input v-model.trim="form.telefono_fijo"></label><label class="wide"><span>Correo electrónico *</span><input v-model.trim="form.email" type="email"></label></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar remitente'}}</button></footer></form></section></div><div v-if="docModal" class="backdrop" @mousedown.self="docModal=false"><section class="modal"><header><div><small>Documento externo de {{selected&&display(selected)}}</small><h2>Registrar documento</h2></div><button @click="docModal=false">×</button></header><form @submit.prevent="saveDoc"><label><span>Tipo documental *</span><select v-model="doc.tipo_documento_id"><option :value="0" disabled>Seleccione</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Número *</span><input v-model.trim="doc.numero"></label><label><span>Asunto *</span><textarea v-model.trim="doc.asunto" rows="3"></textarea></label><label><span>Archivo</span><input type="file" @change="doc.archivo=($event.target as HTMLInputElement).files?.[0]||null"></label><footer><button type="button" class="clear" @click="docModal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar documento'}}</button></footer></form></section></div></div></template>
<style scoped>
.external{--accent:#16885d;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.7rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.62rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero>strong{margin-left:auto;font-size:.64rem}.hero>button,.filters button,.cards footer button,.pagination button,.modal footer button{padding:8px 12px;border:1px solid var(--accent);border-radius:7px;color:#fff;background:var(--accent);font-size:.62rem}.flash{margin-top:14px;padding:11px;border:1px solid #b9dfce;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.68rem}.flash.error{color:#a13f43;border-color:#efcaca;background:#fff4f4}.filters{margin:16px 0;padding:18px;display:grid;grid-template-columns:1fr auto auto;align-items:end;gap:8px;border:1px solid #e2e7ea;border-radius:11px;background:#fff}label>span{display:block;margin-bottom:6px;color:#66737a;font-size:.63rem}input,select,textarea{width:100%;padding:9px 10px;border:1px solid #dae2e6;border-radius:7px;background:#fff;font:inherit;font-size:.68rem}input,select{height:40px}.clear{color:#68757c!important;border-color:#d5dee2!important;background:#fff!important}.notice{padding:45px;text-align:center;border:1px dashed #cbd6dc;border-radius:10px;background:#fff;font-size:.7rem}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.cards article{border:1px solid #dfe6e2;border-top:3px solid var(--accent);border-radius:10px;background:#fff}.cards article>header{padding:15px;display:flex;gap:10px}.avatar{width:40px;height:40px;display:grid;place-items:center;border-radius:50%;color:var(--accent);background:#e8f6f0;font-size:.61rem;font-weight:700}.cards h2{margin:2px 0;font-size:.77rem}.cards small,.cards header span{display:block;color:#89959b;font-size:.56rem}.cards dl{margin:0;padding:0 15px}.cards dl>div{padding:6px 0;display:flex;justify-content:space-between;border-top:1px solid #edf0ee;font-size:.61rem}.cards dd{margin:0}.cards footer{padding:13px 15px;display:flex;gap:5px}.cards footer button{flex:1}.cards .edit{color:#715412;border-color:#f2d28e;background:#ffefc9}.cards .delete{border-color:#bd5050;background:#bd5050}.pagination{padding:18px;display:flex;justify-content:center;gap:12px;align-items:center;font-size:.64rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,600px);max-height:calc(100vh - 40px);overflow:auto;border-radius:12px;background:#fff}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e5eaed}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal>form{padding:20px}.modal form>label,.grid{margin-bottom:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.wide{grid-column:1/-1}.modal footer{display:flex;justify-content:flex-end;gap:7px}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}}@media(max-width:620px){.hero{flex-wrap:wrap}.hero>strong{margin:0}.hero>button{width:100%}.cards,.filters,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
